mapper.select:
SELECT t_maintaining_sprinkler.*, t_sprinkler.* FROM t_maintaining_sprinkler LEFT JOIN t_sprinkler ON t_maintaining_sprinkler.sprinkler_id = t_sprinkler.sprinkler_id
t_sprinkler.deleted_flag = #{queryForm.deletedFlag}
AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})
AND INSTR(t_sprinkler.history,#{queryForm.history})
AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}
AND DATE_FORMAT(t_maintaining_sprinkler.ret_maintainence_date, '%Y-%m-%d') >= #{joinForm.retMaintainenceDateStartTime}
AND DATE_FORMAT(t_maintaining_sprinkler.ret_maintainence_date, '%Y-%m-%d') <= #{joinForm.retMaintainenceDateEndTime}
AND INSTR(t_maintaining_sprinkler.ret_maintainence_reason,#{joinForm.retMaintainenceReason})
AND INSTR(t_maintaining_sprinkler.real_reason,#{joinForm.realReason})
AND INSTR(t_maintaining_sprinkler.customer,#{joinForm.customer})
ORDER BY t_sprinkler.create_time DESC

